trait GameItem { fn draw(&self); }
trait Tickable { fn tick(&mut self); }
struct Ball { x: i32, dx: i32, suspended: bool }

impl GameItem for Ball { fn draw(&self) { ... } }
impl Tickable for Ball {                     // one value, two capabilities
    fn tick(&mut self) { if !self.suspended { self.step(); } }
}
impl Ball { fn step(&mut self) { self.x += self.dx; } }

struct Driver { ball: Rc<RefCell<Ball>> }              // a runtime owns one end
struct BallHandle { driver: Weak<RefCell<Ball>> }      // back-link never owns
